<?php
require_once __DIR__.'/includes/bootstrap.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$rid=filter_input(INPUT_POST,'registration_id',FILTER_VALIDATE_INT);if($rid){$s=$pdo->prepare("UPDATE registrations SET status='cancelled' WHERE id=? AND user_id=? AND status='registered'");$s->execute([$rid,user()['id']]);flash($s->rowCount()?'Registration cancelled.':'Registration could not be cancelled.');}go('my-registrations.php');}
$s=$pdo->prepare('SELECT r.id registration_id,r.status registration_status,e.* FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? ORDER BY r.registered_at DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();$pageTitle='My registrations';require __DIR__.'/includes/header.php';?><h1 class="fw-bold mb-4">My registrations</h1><?php if(!$rows):?><div class="empty"><h2 class="h5">No registrations yet</h2><a href="index.php">Explore events</a></div><?php else:?><div class="panel table-responsive"><table class="table align-middle"><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e(date('d M Y H:i',strtotime($r['event_date'])))?></td><td><?=e($r['venue'])?></td><td><?=e(ucfirst($r['registration_status']))?></td><td><?php if($r['registration_status']==='registered'&&strtotime($r['event_date'])>time()):?><form method="post" data-confirm="Cancel this registration?"><input type="hidden" name="csrf_token" value="<?=e(token())?>"><input type="hidden" name="registration_id" value="<?=(int)$r['registration_id']?>"><button class="btn btn-sm btn-outline-danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php require __DIR__.'/includes/footer.php';?>